// Hard digital-SAT R&W bank questions (conventions). Auto-generated; verified content.
window.SAT_DATA = window.SAT_DATA || {};
(window.SAT_DATA.rwBank = window.SAT_DATA.rwBank || []).push(
{"id": "rw-bnd-a1", "domain": "conventions", "skill": "boundaries", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "Biologists studying the vampire squid, a deep-sea cephalopod named for its cloak-like webbing, have found that its metabolism—one of the lowest ever recorded among free-swimming ______ allows the animal to persist in the oxygen-starved midwater zone it inhabits."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "cephalopods,", "why": "A comma cannot pair with the opening em dash after \"metabolism\" to bracket the nonessential element; matched punctuation is required.", "tag": "unsupported"}, {"text": "cephalopods:", "why": "A colon cannot close a dash-introduced nonessential element, and it wrongly signals that an explanation or list follows.", "tag": "unsupported"}, {"text": "cephalopods—", "why": "The nonessential appositive \"one of the lowest ever recorded among free-swimming cephalopods\" is opened by the em dash after \"metabolism,\" so a matching closing dash is required before the verb \"allows.\""}, {"text": "cephalopods", "why": "Omitting punctuation leaves the nonessential element unclosed, running the appositive directly into the main clause's verb \"allows.\"", "tag": "unsupported"}], "answer": 2},
{"id": "rw-bnd-a2", "domain": "conventions", "skill": "boundaries", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "Because the newly pedestrianized shopping district in central Seoul drew far more weekend foot traffic than the city's transportation planners had ______ several nearby merchants reported their first year-over-year rise in revenue in more than a decade."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "anticipated,", "why": "The sentence opens with the subordinate clause \"Because...anticipated,\" which must be joined to the main clause \"several nearby merchants reported...\" by a comma."}, {"text": "anticipated;", "why": "A semicolon joins two independent clauses, but the \"Because\" clause is dependent and cannot stand on one side of a semicolon.", "tag": "unsupported"}, {"text": "anticipated.", "why": "A period would leave \"Because...anticipated\" as a sentence fragment, since a subordinate clause cannot stand alone.", "tag": "unsupported"}, {"text": "anticipated:", "why": "A colon must follow an independent clause; the introductory \"Because\" clause is dependent, so a colon is unwarranted.", "tag": "unsupported"}], "answer": 0},
{"id": "rw-bnd-a3", "domain": "conventions", "skill": "boundaries", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "To measure how congestion pricing affects neighborhood retailers, an urban-policy team examined three metropolises that had charged drivers to enter their downtown cores for at least a decade: Stockholm, Sweden______ Milan, Italy; and London, England."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "Sweden,", "why": "A comma cannot separate items that already contain internal commas without creating ambiguity about where one item ends and the next begins.", "tag": "unsupported"}, {"text": "Sweden—", "why": "A dash does not mark the boundary between items in a series.", "tag": "unsupported"}, {"text": "Sweden:", "why": "A colon introduces a list or an explanation; it does not separate two items within a series.", "tag": "unsupported"}, {"text": "Sweden;", "why": "Because each item in the series contains an internal comma (city, country), the items must be separated by semicolons, matching the \"Milan, Italy; and London, England\" pattern."}], "answer": 3},
{"id": "rw-bnd-a4", "domain": "conventions", "skill": "boundaries", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "Long dismissed by anglers as a nuisance, the goliath grouper is now recognized as a keystone species that benefits its reef in three important ways______ steadier populations of smaller predators, the wider dispersal of nutrients across the seafloor, and the return of the schooling fish on which many other species depend."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "ways,", "why": "A comma cannot introduce this three-item list after a complete independent clause; a colon is required to signal the enumeration promised by \"three important ways.\"", "tag": "unsupported"}, {"text": "ways:", "why": "A complete independent clause precedes the blank, and a colon correctly introduces the list of noun phrases that specifies the \"three important ways.\""}, {"text": "ways;", "why": "A semicolon must separate independent clauses; what follows is a list of noun phrases, not an independent clause.", "tag": "unsupported"}, {"text": "ways", "why": "Omitting punctuation runs the list directly into the clause, producing a fused construction with no boundary.", "tag": "unsupported"}], "answer": 1},
{"id": "rw-bnd-a5", "domain": "conventions", "skill": "boundaries", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "Marseille's floating breakwaters, a network of anchored barriers engineered to blunt incoming ______ have cut wave heights inside the old harbor by nearly a third since their installation in 2019."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "swells,", "why": "The nonessential appositive \"a network of anchored barriers engineered to blunt incoming swells\" is opened by the comma after \"breakwaters\" and must be closed by a matching comma before the verb \"have cut.\""}, {"text": "swells", "why": "Without the closing comma, the appositive is left unclosed and the subject runs straight into the verb \"have cut.\"", "tag": "unsupported"}, {"text": "swells;", "why": "A semicolon must join two independent clauses; placing one here severs the subject \"breakwaters\" from its verb \"have cut.\"", "tag": "unsupported"}, {"text": "swells:", "why": "A colon must follow an independent clause and introduce an explanation or list; the words before the blank are not independent.", "tag": "unsupported"}], "answer": 0},
{"id": "rw-bnd-b1", "domain": "conventions", "skill": "boundaries", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "To determine whether regional microbial communities shape bread flavor, food scientist Elena Vasquez collected sourdough starters from three sites: a bakery in Oaxaca, Mexico, whose starter incorporates wild yeasts from agave; a farmhouse in Vermont, ______ and a mill in Osaka, Japan, whose starter is refreshed with locally grown rice flour."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "whose starter has been maintained for four decades,", "why": "Commas are the standard dividers in simple lists, but this list's items contain internal commas ('Oaxaca, Mexico,' 'Osaka, Japan,'), so a comma here would blur the boundary between the second and third sites; the first boundary ('agave;') already establishes semicolons as the item dividers.", "tag": "true-but-irrelevant"}, {"text": "whose starter has been maintained for four decades", "why": "Some boundary mark is required to close the Vermont item before 'and a mill in Osaka'; with no punctuation, the second and third items of the list run together unmarked.", "tag": "unsupported"}, {"text": "whose starter, has been maintained for four decades;", "why": "The closing semicolon is correctly placed, but the comma between the subject 'starter' and its verb 'has been maintained' illegally interrupts the clause.", "tag": "reversed"}, {"text": "whose starter has been maintained for four decades;", "why": "Correct. Because the list items contain internal commas, semicolons must mark the boundaries between items; this choice closes the Vermont item with a semicolon — matching the earlier boundary 'agave;' — and leaves the clause 'whose starter has been maintained' uninterrupted."}], "answer": 3},
{"id": "rw-bnd-b2", "domain": "conventions", "skill": "boundaries", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "In 1629, the Tokugawa shogunate banned women from Japan's kabuki stage, ostensibly to protect public morals. The prohibition, however, did not diminish audiences' appetite for female ______ specialists known as onnagata—men trained from childhood in a stylized repertoire of feminine gesture and speech—became some of the form's most celebrated stars."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "roles; instead,", "why": "Correct. 'The prohibition...did not diminish...' and 'specialists...became...' are both independent clauses, so a semicolon is required between them; the conjunctive adverb 'instead' cannot join clauses by itself and is properly followed by a comma."}, {"text": "roles, instead,", "why": "'Instead' is a conjunctive adverb, not a coordinating conjunction, so a comma before it cannot join the two independent clauses; the result is a comma splice.", "tag": "unsupported"}, {"text": "roles instead,", "why": "Attaching 'instead' to the first clause ('...appetite for female roles instead') sounds complete but still leaves a bare comma joining two independent clauses — a comma splice.", "tag": "reversed"}, {"text": "roles; instead of", "why": "The semicolon is correctly placed, but 'instead of' is a preposition: it absorbs 'specialists known as onnagata' as its object and leaves what follows the semicolon without a subject, producing a fragment.", "tag": "true-but-irrelevant"}], "answer": 0},
{"id": "rw-bnd-b3", "domain": "conventions", "skill": "boundaries", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "Nixtamalization—the ancient Mesoamerican technique of simmering dried maize in an alkaline solution of water and wood ash or slaked ______ transforms the grain in ways that milling alone cannot, freeing bound niacin and softening the kernel's tough pericarp for grinding."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "lime,", "why": "Commas can set off an appositive, but only as a matched pair; this appositive was opened with a dash after 'Nixtamalization,' so a comma cannot close it.", "tag": "true-but-irrelevant"}, {"text": "lime—", "why": "Correct. The appositive describing nixtamalization opens with a dash, so it must close with a matching dash, restoring the main clause 'Nixtamalization...transforms the grain.'"}, {"text": "lime;", "why": "A semicolon must have an independent clause on each side; here it would sever the subject 'Nixtamalization' from its verb 'transforms' while leaving the dash-opened appositive unclosed.", "tag": "unsupported"}, {"text": "lime, which", "why": "'Which' pulls 'transforms' into a relative clause, so the sentence never supplies a main verb for 'Nixtamalization'; the result is a fragment with an unclosed dash.", "tag": "unsupported"}], "answer": 1},
{"id": "rw-bnd-b4", "domain": "conventions", "skill": "boundaries", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "The claim that the Federal Theatre Project's 1936 Macbeth—staged in Harlem with an all-Black cast and directed by a twenty-year-old Orson Welles—succeeded merely as a ______ hard to square with the production's record: after sold-out runs at the Lafayette Theatre, the show toured the country to packed houses for months."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "novelty, is", "why": "The long subject invites a pause, but no convention permits a comma between a subject and its verb; the subject is the entire noun phrase 'The claim that...succeeded merely as a novelty,' and 'is' is its verb.", "tag": "true-but-irrelevant"}, {"text": "novelty; is", "why": "A semicolon requires an independent clause on each side; 'The claim that...novelty' is a noun phrase, not a clause, because 'succeeded' belongs to the embedded 'that' clause.", "tag": "unsupported"}, {"text": "novelty is", "why": "Correct. The whole noun phrase 'The claim that...succeeded merely as a novelty' is the subject and 'is' is its verb; Standard English allows no punctuation between a subject and its verb, however long the subject."}, {"text": "novelty—is", "why": "The dash pair enclosing 'staged...Welles' has already closed, so a third, unpaired dash would illegally split the subject from its verb 'is.'", "tag": "reversed"}], "answer": 2},
{"id": "rw-bnd-b5", "domain": "conventions", "skill": "boundaries", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "During the 1880s, the self-taught plant breeder Luther Burbank adopted a method that unsettled his more cautious ______ he grafted seedlings from thousands of experimental plum crosses onto mature trees, allowing the fruit of many hybrids to be evaluated in a single growing season rather than over decades."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "contemporaries,", "why": "'He grafted seedlings...' is an independent clause, and a comma alone cannot attach it to the independent clause before the blank; this is a comma splice.", "tag": "unsupported"}, {"text": "contemporaries:", "why": "Correct. The independent clause 'Burbank adopted a method that unsettled his more cautious contemporaries' may be followed by a colon to introduce the explanation of that method, and 'he grafted seedlings...' delivers exactly that explanation."}, {"text": "contemporaries", "why": "With no punctuation, two independent clauses run together ('...contemporaries he grafted...'), producing a fused sentence.", "tag": "unsupported"}, {"text": "contemporaries; whereby", "why": "A semicolon alone could join these two clauses, but 'whereby' subordinates the second one, leaving a dependent fragment after the semicolon.", "tag": "true-but-irrelevant"}], "answer": 1},
{"id": "rw-bnd-c1", "domain": "conventions", "skill": "boundaries", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "The 1861 unveiling of Archaeopteryx handed Darwin's defenders precisely the specimen they had long been waiting ______ possessed both feathers and a full set of reptilian teeth."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "for: the fossil", "why": "A colon joins the independent clause ('...they had long been waiting for') to the independent clause that explains it ('the fossil possessed both feathers and a full set of reptilian teeth'), and nothing wrongly separates the subject 'the fossil' from its verb 'possessed.'"}, {"text": "for, the fossil", "why": "Only a comma between the two independent clauses creates a comma splice.", "tag": "unsupported"}, {"text": "for the fossil", "why": "With no punctuation, 'waiting for the fossil possessed' fuses the two clauses into an ungrammatical run-on.", "tag": "unsupported"}, {"text": "for: the fossil,", "why": "The colon is correct, but the added comma illegally separates the subject 'the fossil' from its verb 'possessed.'", "tag": "unsupported"}], "answer": 0},
{"id": "rw-bnd-c2", "domain": "conventions", "skill": "boundaries", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "Ralph Waldo Emerson's 1841 essay \"Self-Reliance\" compresses its philosophy into vivid figures of speech. In the essay's central ______ instance, society is likened to a joint-stock company that conspires against the individuality of each of its members."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "metaphor. For", "why": "A period leaves 'In the essay's central metaphor' standing alone as a sentence fragment.", "tag": "unsupported"}, {"text": "metaphor; for", "why": "A semicolon requires an independent clause before it, but 'In the essay's central metaphor' is only an introductory phrase.", "tag": "unsupported"}, {"text": "metaphor, for", "why": "The sentence is a single independent clause whose subject is 'society' and verb 'is likened'; 'In the essay's central metaphor' is an introductory phrase and 'for instance' a parenthetical, so a comma is the only mark that fits."}, {"text": "metaphor: for", "why": "A colon also demands a complete independent clause before it, which the introductory phrase is not.", "tag": "unsupported"}], "answer": 2},
{"id": "rw-fss-a1", "domain": "conventions", "skill": "form-structure-sense", "difficulty": "hard", "targetSeconds": 50, "wordId": "", "passage": {"type": "single", "text": "Far beyond the orbit of Neptune, in a region of the solar system once assumed to be nearly empty, ______ two of the largest known trans-Neptunian objects: Eris, whose unusual density suggests a largely rocky interior, and Makemake, whose reddish surface is coated with frozen methane."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "lies", "why": "The singular \"lies\" agrees with the nearby singular nouns \"region\" and \"solar system,\" but those sit inside prepositional phrases; the true subject follows the verb in this inverted sentence and is plural.", "tag": "reversed"}, {"text": "lie", "why": "The sentence is inverted: the subject, the plural noun phrase \"two of the largest known trans-Neptunian objects,\" comes after the verb, so the plural present-tense \"lie\" is required."}, {"text": "has lain", "why": "Singular \"has\" clashes with the plural inverted subject \"two of the largest known trans-Neptunian objects,\" and the perfect aspect wrongly implies a completed state rather than a permanent fact.", "tag": "reversed"}, {"text": "lying", "why": "The participle \"lying\" leaves the sentence without any finite verb, producing a fragment: nothing then asserts where the two objects are.", "tag": "unsupported"}], "answer": 1},
{"id": "rw-fss-a2", "domain": "conventions", "skill": "form-structure-sense", "difficulty": "hard", "targetSeconds": 50, "wordId": "", "passage": {"type": "single", "text": "NASA's Dragonfly rotorcraft, scheduled for launch in 2028, is expected to reach Saturn's largest moon, Titan, in 2034. By the time the eight-rotor vehicle begins sampling the moon's organic-rich dunes, it ______ through interplanetary space for roughly six years, sealed inside a protective aeroshell for the entire cruise."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "had traveled", "why": "Past perfect places the traveling before a past reference point, but \"By the time the vehicle begins sampling\" sets a future reference point (2034), so the tense points in the wrong direction.", "tag": "reversed"}, {"text": "traveled", "why": "Simple past locates the six-year cruise wholly in the past, yet the passage says the craft has not even launched; the journey will be completed only by a future moment.", "tag": "reversed"}, {"text": "travels", "why": "Simple present cannot express an action that will already be finished by the future reference point \"by the time the vehicle begins sampling\"; it asserts a habitual or current action instead.", "tag": "unsupported"}, {"text": "will have traveled", "why": "The phrase \"By the time the eight-rotor vehicle begins sampling\" establishes a future deadline (arrival in 2034), so the future perfect is required for an action completed before that future point."}], "answer": 3},
{"id": "rw-fss-a3", "domain": "conventions", "skill": "form-structure-sense", "difficulty": "hard", "targetSeconds": 50, "wordId": "", "passage": {"type": "single", "text": "The following text is adapted from Thomas Hardy's 1878 novel The Return of the Native. Evening had so thickened over the heath that furze, ridge, and sky were of one somber tone. Worn into the turf by generations of packhorses and long since surrendered to the encroaching heather, ______"}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "the ancient track was scarcely distinguishable to the traveler from the wild ground on either side.", "why": "The introductory participial phrase \"Worn into the turf by generations of packhorses and long since surrendered to the heather\" must modify the noun that follows it, and only \"the ancient track\" can logically have been worn into the turf and overgrown."}, {"text": "the traveler could scarcely distinguish the ancient track from the wild ground on either side.", "why": "Grammatical on its own, but it makes the modifier dangle: it absurdly claims the traveler was worn into the turf by packhorses and surrendered to the heather.", "tag": "true-but-irrelevant"}, {"text": "it was scarcely possible for the traveler to distinguish the ancient track from the wild ground on either side.", "why": "The expletive \"it\" gives the participial phrase nothing logical to modify, so the description of being worn into the turf attaches to no actual noun.", "tag": "true-but-irrelevant"}, {"text": "the wild ground on either side could scarcely be distinguished from the ancient track.", "why": "This swaps the roles of the nouns: the modifier now describes \"the wild ground,\" but it was the track, not the surrounding ground, that packhorses wore into the turf.", "tag": "reversed"}], "answer": 0},
{"id": "rw-fss-a4", "domain": "conventions", "skill": "form-structure-sense", "difficulty": "hard", "targetSeconds": 50, "wordId": "", "passage": {"type": "single", "text": "Planetary scientists attribute Mars's transformation from a comparatively warm, wet world into a frozen desert to three interlocking processes: the collapse of the planet's protective magnetic field, the stripping of its atmosphere by charged particles streaming from the Sun, and ______"}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "its remaining surface water was sequestered as ice beneath the regolith.", "why": "A finite clause breaks the parallel series of noun phrases (\"the collapse of...,\" \"the stripping of...\") and cannot serve as the third object of \"attribute...to.\"", "tag": "unsupported"}, {"text": "that its remaining surface water became sequestered as ice beneath the regolith.", "why": "A that-clause cannot complete the list: the first two items are noun phrases built on \"the ___ of,\" and \"attribute X to that...\" is not idiomatic Standard English.", "tag": "unsupported"}, {"text": "the sequestration of its remaining surface water as ice beneath the regolith.", "why": "Only this choice matches the established pattern of the series—\"the collapse of...,\" \"the stripping of...,\" \"the sequestration of...\"—keeping all three items parallel noun phrases governed by \"attribute...to.\""}, {"text": "sequestering its remaining surface water as ice beneath the regolith.", "why": "The bare gerund phrase abandons the \"the ___ of\" structure of the first two list items, so the series is no longer parallel; it also implies an unnamed agent performing the sequestering.", "tag": "reversed"}], "answer": 2},
{"id": "rw-fss-a5", "domain": "conventions", "skill": "form-structure-sense", "difficulty": "hard", "targetSeconds": 50, "wordId": "", "passage": {"type": "single", "text": "The following text is adapted from George Eliot's 1871 novel Middlemarch. Dorothea had ridden out that morning to survey the farms at the far edge of the estate. Neither the laborers' cottages, with their sunken thatch and broken casements, nor the strip of land that stretched behind them ______ in a condition that a conscientious landlord could contemplate without shame."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "were", "why": "Plural \"were\" is attracted by the nearby plurals \"cottages\" and \"them,\" but in a neither...nor construction the verb agrees with the nearer subject, the singular \"strip of land.\"", "tag": "reversed"}, {"text": "was", "why": "With subjects joined by neither...nor, the verb agrees with the nearer one—the singular \"the strip of land that stretched behind them\"—and past-tense \"was\" matches the narrative's past-tense frame (\"had ridden out\")."}, {"text": "have been", "why": "\"Have been\" is both plural, disagreeing with the nearer singular subject \"strip of land,\" and present perfect, clashing with the passage's past-tense narration.", "tag": "reversed"}, {"text": "being", "why": "The participle \"being\" supplies no finite verb, reducing the long neither...nor construction to a sentence fragment.", "tag": "unsupported"}], "answer": 1},
{"id": "rw-fss-a6", "domain": "conventions", "skill": "form-structure-sense", "difficulty": "hard", "targetSeconds": 50, "wordId": "", "passage": {"type": "single", "text": "In 2020, astronomers ______ to identify the sources of fast radio bursts—millisecond-long flashes of radio energy that had previously been traced only to distant galaxies—linked one such burst to a magnetar, a highly magnetized stellar remnant, inside the Milky Way."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "sought", "why": "The finite verb \"sought\" collides with the sentence's main verb \"linked,\" yielding two finite verbs for one subject with no conjunction between them.", "tag": "unsupported"}, {"text": "have sought", "why": "Besides creating a second finite verb alongside \"linked,\" the present perfect clashes with the completed past event dated \"In 2020.\"", "tag": "reversed"}, {"text": "seeking", "why": "The participle \"seeking\" begins a modifying phrase that describes \"astronomers,\" leaving \"linked\"—after the long dash-enclosed interruption—as the sentence's single main verb."}, {"text": "were seeking", "why": "\"Were seeking\" is a finite verb, so the subject \"astronomers\" would govern both it and \"linked\" without any coordinating word, producing an ungrammatical sentence.", "tag": "unsupported"}], "answer": 2},
{"id": "rw-fss-b1", "domain": "conventions", "skill": "form-structure-sense", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "The synchronized flashing of male fireflies in a dense riverside colony, a behavior that early naturalists dismissed as the accidental alignment of thousands of independently blinking insects, ______ now understood to emerge from each male's continual adjustment of its own rhythm to those of its nearest neighbors."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "are", "why": "Agreement error: the plural verb is pulled toward the nearby plural nouns (insects, neighbors), but the grammatical subject is the singular noun phrase \"The synchronized flashing.\"", "tag": "unsupported"}, {"text": "were", "why": "Wrong in both number and tense: the subject \"flashing\" is singular, and the adverb \"now\" establishes present time, so a plural past-tense verb cannot be correct.", "tag": "unsupported"}, {"text": "is", "why": "The singular subject is \"The synchronized flashing,\" separated from its verb by a long appositive; a singular present-tense verb agrees with it and matches \"now understood.\""}, {"text": "have been", "why": "Agreement error: a singular subject would require \"has been,\" not the plural \"have been,\" which is misled by the intervening plural nouns.", "tag": "unsupported"}], "answer": 2},
{"id": "rw-fss-b2", "domain": "conventions", "skill": "form-structure-sense", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "When economist Elena Marchetti published her influential 1981 study of medieval Alpine commons, she relied on parish ledgers demonstrating that, generations before any central authority intervened, village councils ______ enforceable ceilings on the number of livestock each household could graze—evidence that unsettled the long-standing assumption that shared pastures inevitably deteriorate."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "had imposed", "why": "The councils' action occurred \"generations before\" other past events (\"published,\" \"intervened\"); the past perfect correctly marks this earlier action within a past-tense narration."}, {"text": "impose", "why": "The present tense clashes with the firmly past narration (\"published,\" \"relied,\" \"intervened\") describing events completed centuries ago.", "tag": "unsupported"}, {"text": "have imposed", "why": "The present perfect links a past action to the present moment, but the councils' action belongs entirely to a completed past that predates Marchetti's 1981 study.", "tag": "unsupported"}, {"text": "will have imposed", "why": "Reversed in time: the future perfect projects completion before a future point, yet the councils acted in the distant past, not the future.", "tag": "reversed"}], "answer": 0},
{"id": "rw-fss-b3", "domain": "conventions", "skill": "form-structure-sense", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "Naked mole-rats pass nearly their entire lives underground, carving communal burrows in a ceaseless search for edible tubers. Tracking the foraging routes of these rodents through a network of subterranean tubes for six months, ______"}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "the excavation patterns of the colony pointed clearly toward newly sprouted tubers.", "why": "Dangling modifier: the introductory phrase must describe whoever did the tracking, but excavation patterns cannot track foraging routes.", "tag": "unsupported"}, {"text": "it became apparent that the colony concentrated its digging near newly sprouted tubers.", "why": "Dangling modifier: the placeholder \"it\" cannot perform the action of \"Tracking,\" leaving the opening phrase without a logical subject.", "tag": "unsupported"}, {"text": "the colony's digging was found to concentrate near newly sprouted tubers.", "why": "Dangling modifier: the subject \"the colony's digging\" did not track the foraging routes, so the modifier attaches to the wrong noun.", "tag": "unsupported"}, {"text": "a team of biologists determined that the colony concentrated its digging near newly sprouted tubers.", "why": "The introductory participial phrase \"Tracking the foraging routes\" correctly modifies \"a team of biologists,\" the only subject capable of performing the tracking."}], "answer": 3},
{"id": "rw-fss-b4", "domain": "conventions", "skill": "form-structure-sense", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "In assessing three rural microloan programs, Okonkwo's audit team recorded how quickly borrowers repaid their initial loans, whether participating households increased their savings, and ______"}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "the reinvestment of the loans in local enterprises.", "why": "Not parallel: this is a noun phrase, whereas the first two list items are subordinate clauses (\"how quickly...,\" \"whether...\").", "tag": "unsupported"}, {"text": "how often the loans were reinvested in local enterprises.", "why": "This subordinate clause (\"how often the loans were reinvested\") matches the clause structure of the first two items, keeping the three-part list parallel."}, {"text": "reinvesting the loans in local enterprises.", "why": "Not parallel: a gerund phrase does not match the subject-verb clauses that make up the first two items of the series.", "tag": "unsupported"}, {"text": "local enterprises receiving any reinvested loans.", "why": "Not parallel: this noun-plus-participle phrase breaks the pattern set by the two preceding subordinate clauses in the list.", "tag": "unsupported"}], "answer": 1},
{"id": "rw-fss-b5", "domain": "conventions", "skill": "form-structure-sense", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "Among the several forces that Delgado's model identifies as accelerating rural wage growth ______ the seasonal migration of laborers to distant coastal harvests, a movement that reshapes local labor supply months before employers adjust their pay."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "is", "why": "In this inverted sentence the subject follows the verb: the singular \"the seasonal migration\" is the subject, so the singular present-tense \"is\" agrees with it and with \"identifies.\""}, {"text": "are", "why": "Agreement error: the plural verb is attracted to \"forces,\" which sits in the opening prepositional phrase and is not the subject of the sentence.", "tag": "unsupported"}, {"text": "were", "why": "Wrong in number and tense: the subject \"migration\" is singular, and the surrounding present-tense verbs (\"identifies,\" \"reshapes,\" \"adjust\") establish present time.", "tag": "unsupported"}, {"text": "have been", "why": "Agreement error: a singular subject would require \"has been,\" and the plural form is misled by \"forces\" in the introductory phrase.", "tag": "unsupported"}], "answer": 0},
{"id": "rw-fss-b6", "domain": "conventions", "skill": "form-structure-sense", "difficulty": "hard", "targetSeconds": 50, "passage": {"type": "single", "text": "Ecologist Marcus Feldman projects that by the time the reintroduced wolves finish their third breeding season in the valley, the resident elk herds ______ their grazing away from the exposed streambanks, giving the willow and aspen seedlings that have been overbrowsed for decades a chance to recover."}, "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": [{"text": "shifted", "why": "The simple past contradicts the forward-looking frame (\"projects that by the time...\"), which describes events expected to be complete at a future point.", "tag": "unsupported"}, {"text": "have shifted", "why": "The present perfect treats the shift as already completed by now, but the sentence forecasts a change to be finished only by a future milestone.", "tag": "unsupported"}, {"text": "will have shifted", "why": "The future perfect fits the projection precisely: the herds' shift will be complete \"by the time\" the wolves finish a future breeding season."}, {"text": "had shifted", "why": "Reversed in time: the past perfect marks an action completed before a past reference point, yet the reference point here (\"by the time...finish\") lies in the future.", "tag": "reversed"}], "answer": 2}
);
